import { t, type DeepSet } from "../types";

/** Prosperity and Biblical Stewardship: the Spirit-led teaching for each lesson. */
export const DEEP: DeepSet = {
  "c-biblical-prosperity": {
    revelation: t(
      "True prosperity is not having more in your hands but having God in your heart and being at peace with Him in whatever you have.",
      "Ang tunay na kasaganaan ay hindi pagkakaroon ng mas marami sa kamay mo kundi pagkakaroon ng Diyos sa puso mo at kapayapaan sa Kanya anuman ang mayroon ka."
    ),
    mainTruth: t(
      "Biblical prosperity is shalom: wholeness and flourishing under God's rule. The blessed person in Psalm 1 delights in God's law and is like a tree that bears fruit in its season (Psalm 1:1-3). Success in Joshua 1:8 is tied to meditating on and obeying God's word. John's greeting, \"I pray that all may go well with you... as it goes well with your soul\" (3 John 2), shows God cares for the whole person. But Paul warns against those who imagine \"godliness is a means of gain,\" and declares, \"godliness with contentment is great gain\" (1 Timothy 6:5-6). Paul himself knew both plenty and hunger, and learned to be content in Christ who strengthens him (Philippians 4:11-13).",
      "Ang biblikal na kasaganaan ay shalom: kabuuan at pag-unlad sa ilalim ng paghahari ng Diyos. Ang pinagpalang tao sa Awit 1 ay nagagalak sa kautusan ng Diyos at parang punong namumunga sa tamang panahon (Awit 1:1-3). Ang tagumpay sa Josue 1:8 ay nakatali sa pagbubulay at pagsunod sa salita ng Diyos. Ang pagbati ni Juan, \"Ipinapanalangin kong maging mabuti ang lahat sa iyo... gaya ng pagiging mabuti ng iyong kaluluwa\" (3 Juan 2), ay nagpapakitang nagmamalasakit ang Diyos sa buong pagkatao. Pero nagbabala si Pablo laban sa mga nag-aakalang \"ang kabanalan ay paraan ng pakinabang,\" at sinabi niya, \"ang kabanalan na may kasiyahan ay malaking pakinabang\" (1 Timoteo 6:5-6). Si Pablo mismo ay nakaranas ng kasaganaan at gutom, at natutong maging kontento kay Cristo na nagpapalakas sa kanya (Filipos 4:11-13)."
    ),
    insight: [
      t(
        "Many Filipinos have heard two extreme messages. One says, \"If you have enough faith and give enough seed, God will make you rich.\" The other says, \"Poverty is holy; money is dirty.\" Both miss the Bible. God is not against provision, work or savings; Abraham, Job and Lydia had wealth. But Scripture never promises that every faithful believer will be rich, and it warns that the desire to be rich plunges people into ruin (1 Timothy 6:9). God's promise is to provide and to be enough, not to make us wealthy.",
        "Maraming Pilipino ang nakarinig ng dalawang sukdulang mensahe. Sabi ng isa, \"Kung sapat ang pananampalataya mo at sapat ang ibinibigay mong binhi, payayamanin ka ng Diyos.\" Sabi naman ng isa, \"Banal ang kahirapan; marumi ang pera.\" Pareho silang lihis sa Bibliya. Hindi kontra ang Diyos sa paglalaan, trabaho o ipon; may yaman sina Abraham, Job at Lydia. Pero hindi kailanman ipinangako ng Kasulatan na yayaman ang bawat tapat na mananampalataya, at nagbababala ito na ang paghahangad na yumaman ay nagtutulak sa tao sa kapahamakan (1 Timoteo 6:9). Ang pangako ng Diyos ay maglaan at maging sapat, hindi ang payamanin tayo."
      ),
      t(
        "Notice Philippians 4:13, perhaps the most misused verse in the Philippines. \"I can do all things through Him who strengthens me\" is not about winning a contest or getting a promotion. In context, Paul is saying he can be content whether full or hungry, because Christ strengthens him. Biblical prosperity includes the power to be faithful and joyful even in lack.",
        "Pansinin ang Filipos 4:13, marahil ang pinakamaling nagagamit na talata sa Pilipinas. Ang \"Kaya kong gawin ang lahat ng bagay sa pamamagitan Niya na nagpapalakas sa akin\" ay hindi tungkol sa pagkapanalo sa paligsahan o pagkuha ng promotion. Sa konteksto, sinasabi ni Pablo na kaya niyang maging kontento busog man o gutom, dahil pinalalakas siya ni Cristo. Kasama sa biblikal na kasaganaan ang lakas na manatiling tapat at masaya kahit sa kakulangan."
      ),
    ],
    life: [
      t(
        "Two OFWs worked side by side in Kuwait for ten years. Rodel sent most of his salary home, built a big house, and bought a car for show, but his marriage broke and his children barely knew him. Dante built a smaller house, saved steadily, called home every night, served in a Filipino fellowship, and came home with a strong family and a small business. Which one prospered? The world measures the house. God measures the whole life: soul, family, character and fruit.",
        "Sampung taong magkatabing nagtrabaho sa Kuwait ang dalawang OFW. Ipinadala ni Rodel ang halos lahat ng sahod niya, nagpatayo ng malaking bahay, at bumili ng kotse para ipakita, pero nasira ang pagsasama nila ng asawa niya at halos hindi siya kilala ng mga anak niya. Mas maliit na bahay ang ipinatayo ni Dante, regular na nag-ipon, tumatawag sa bahay gabi-gabi, naglingkod sa isang Filipino fellowship, at umuwi nang may matatag na pamilya at maliit na negosyo. Sino ang umunlad? Ang sukat ng mundo ay ang bahay. Ang sukat ng Diyos ay ang buong buhay: kaluluwa, pamilya, pagkatao at bunga."
      ),
      t(
        "Jeremiah 29:7 adds another dimension: God told the exiles to seek the welfare of the city where they were sent. Biblical prosperity is not only personal; it overflows. A prosperous believer blesses the workplace, the barangay and the church, not only his own bank account.",
        "May isa pang dimensyon ang Jeremias 29:7: sinabihan ng Diyos ang mga bihag na hanapin ang ikabubuti ng lungsod na pinagdalhan sa kanila. Ang biblikal na kasaganaan ay hindi lang personal; umaapaw ito. Ang masaganang mananampalataya ay nagpapala sa trabaho, sa barangay at sa simbahan, hindi lang sa sarili niyang bank account."
      ),
    ],
    twist: t(
      "Psalm 1 says the blessed man is like a tree. Trees do not exist to eat their own fruit; their fruit is for others. A mango tree never tastes a single mango. In God's Kingdom, you are prospering when others are being fed through your life. The richest person in God's eyes may be the one with the least money but the most fruit, like the widow whose two coins Jesus praised.",
      "Sabi ng Awit 1, ang pinagpalang tao ay parang puno. Ang puno ay hindi nabubuhay para kainin ang sarili nitong bunga; para sa iba ang bunga nito. Hindi kailanman natitikman ng puno ng mangga ang kahit isang mangga. Sa Kaharian ng Diyos, umuunlad ka kapag napapakain ang iba sa pamamagitan ng buhay mo. Ang pinakamayaman sa paningin ng Diyos ay maaaring ang may pinakakaunting pera pero pinakamaraming bunga, gaya ng balong pinuri ni Hesus dahil sa dalawang barya."
    ),
    confirm: [
      t("Proverbs 10:22: the blessing of the Lord makes rich, and He adds no sorrow with it.", "Kawikaan 10:22: ang pagpapala ng Panginoon ang nagpapayaman, at hindi Niya dinadagdagan ng kalungkutan."),
      t("Proverbs 30:8-9: \"Give me neither poverty nor riches; feed me with the food that is needful for me.\"", "Kawikaan 30:8-9: \"Huwag Mo akong bigyan ng kahirapan o kayamanan; pakainin Mo ako ng pagkaing kailangan ko.\""),
      t("Mark 12:41-44: the widow's two coins were more than all the rich gave.", "Marcos 12:41-44: ang dalawang barya ng balo ay higit pa sa lahat ng ibinigay ng mayayaman."),
      t("Revelation 3:17: a rich church that was actually \"poor, blind and naked.\"", "Pahayag 3:17: isang mayamang iglesya na sa totoo ay \"dukha, bulag at hubad.\""),
    ],
    heart: [
      t(
        "Redefine success: from \"How much do I have?\" to \"How faithful and fruitful am I with what God gave me?\"",
        "Baguhin ang kahulugan ng tagumpay: mula sa \"Gaano karami ang mayroon ako?\" tungo sa \"Gaano ako katapat at kamabunga sa ibinigay ng Diyos sa akin?\""
      ),
      t(
        "Test every teaching about money with Scripture. If a message makes God a means to wealth instead of the treasure Himself, walk away from it.",
        "Suriin gamit ang Kasulatan ang bawat turo tungkol sa pera. Kung ginagawang paraan para yumaman ang Diyos sa halip na Siya mismo ang kayamanan, lumayo ka rito."
      ),
    ],
    questions: [
      t("How would you have defined prosperity before this lesson? How has it changed?", "Paano mo binigyang-kahulugan ang kasaganaan bago ang araling ito? Paano ito nagbago?"),
      t("Have you been influenced by teaching that promises wealth in exchange for faith or giving?", "Naimpluwensyahan ka ba ng turong nangangako ng yaman kapalit ng pananampalataya o pagbibigay?"),
      t("Which area of your life (soul, family, health, money) is least \"whole\" right now?", "Aling bahagi ng buhay mo (kaluluwa, pamilya, kalusugan, pera) ang pinakahindi \"buo\" ngayon?"),
      t("Who is being fed by the fruit of your life?", "Sino ang napapakain ng bunga ng buhay mo?"),
    ],
    actions: [
      t("Write your own definition of a prosperous life based on Psalm 1 and 1 Timothy 6:6.", "Isulat ang sarili mong kahulugan ng masaganang buhay batay sa Awit 1 at 1 Timoteo 6:6."),
      t("Thank God out loud for ten non-money blessings in your life today.", "Pasalamatan nang malakas ang Diyos para sa sampung pagpapalang hindi pera sa buhay mo ngayon."),
      t("Do one thing this week to seek the welfare of your workplace, barangay or church.", "Gumawa ng isang bagay ngayong linggo para hanapin ang ikabubuti ng trabaho, barangay o simbahan mo."),
    ],
    prayer: t(
      "Lord, You are my true treasure. Forgive me for the times I measured my life by money or compared myself with others. Teach me that godliness with contentment is great gain. Make me like a tree planted by streams of water, rooted in Your word and bearing fruit for others. Whether I have much or little, strengthen me to be faithful and joyful in You. In Jesus' name, Amen.",
      "Panginoon, Ikaw ang tunay kong kayamanan. Patawarin Mo ako sa mga panahong sinukat ko ang buhay ko sa pera o ikinumpara ang sarili ko sa iba. Turuan Mo ako na ang kabanalan na may kasiyahan ay malaking pakinabang. Gawin Mo akong parang punong itinanim sa tabi ng mga batis, nakaugat sa salita Mo at namumunga para sa iba. Marami man o kaunti ang mayroon ako, palakasin Mo ako na maging tapat at masaya sa Iyo. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-gods-provision": {
    revelation: t(
      "God provides daily bread, not a ten-year stockpile, because He wants you to depend on Him daily, not only on what is in the bank.",
      "Nagbibigay ang Diyos ng tinapay sa araw-araw, hindi sampung taong imbak, dahil gusto Niyang umasa ka sa Kanya araw-araw, hindi lang sa laman ng bangko."
    ),
    mainTruth: t(
      "On Mount Moriah, Abraham named the place \"The Lord will provide\" (Genesis 22:14). In the wilderness, God rained bread from heaven, enough for each day, and the manna that was hoarded bred worms (Exodus 16:4, 16-21). Jesus taught us to pray, \"Give us this day our daily bread\" (Matthew 6:11), and promised that when we seek first God's kingdom, \"all these things will be added to you\" (Matthew 6:33). God fed Elijah through a poor widow whose flour and oil did not run out (1 Kings 17:8-16). \"My God will supply every need of yours according to His riches in glory in Christ Jesus\" (Philippians 4:19).",
      "Sa Bundok Moria, pinangalanan ni Abraham ang lugar na \"Ang Panginoon ang maglalaan\" (Genesis 22:14). Sa ilang, nagpaulan ang Diyos ng tinapay mula sa langit, sapat para sa bawat araw, at inuod ang manang inimbak (Exodo 16:4, 16-21). Tinuruan tayo ni Hesus na manalangin, \"Bigyan Mo kami ngayon ng aming kakanin sa araw-araw\" (Mateo 6:11), at nangako na kapag hinanap muna natin ang kaharian ng Diyos, \"idaragdag sa inyo ang lahat ng ito\" (Mateo 6:33). Pinakain ng Diyos si Elias sa pamamagitan ng isang mahirap na balo na hindi naubusan ng harina at langis (1 Hari 17:8-16). \"Ibibigay ng aking Diyos ang lahat ng inyong kailangan ayon sa Kanyang kayamanan sa kaluwalhatian kay Cristo Hesus\" (Filipos 4:19)."
    ),
    insight: [
      t(
        "Philippians 4:19 says \"every need,\" not every want. And it was written to the Philippians right after they had generously supported Paul's ministry (4:15-18). God's provision is not a blank check for our dreams; it is a faithful Father's commitment to give what we truly need to do His will. Sometimes He provides through a raise; sometimes through a brother's help; sometimes by teaching us to need less.",
        "Ang sinasabi ng Filipos 4:19 ay \"lahat ng kailangan,\" hindi lahat ng gusto. At isinulat ito sa mga taga-Filipos pagkatapos nilang masaganang suportahan ang ministeryo ni Pablo (4:15-18). Ang pagtustos ng Diyos ay hindi blangkong tseke para sa mga pangarap natin; ito ang pangako ng tapat na Ama na ibibigay ang tunay nating kailangan para gawin ang kalooban Niya. Minsan naglalaan Siya sa pamamagitan ng dagdag-sahod; minsan sa tulong ng kapatid; minsan sa pagtuturo sa atin na mangailangan nang mas kaunti."
      ),
      t(
        "The widow of Zarephath is surprising. God sent Elijah to be fed by a woman who had only enough for one last meal. God's provision often flows through obedience that looks risky: she fed the prophet first. Notice, though, that she received no mansion, only a jar that did not run dry. God's provision is often \"just enough, just in time,\" so that we keep looking to Him.",
        "Nakakagulat ang balo ng Sarepta. Isinugo ng Diyos si Elias para pakainin ng isang babaeng sapat na lang ang pagkain para sa isang huling hapunan. Madalas dumadaloy ang pagtustos ng Diyos sa pagsunod na mukhang mapanganib: inuna niyang pakainin ang propeta. Pero pansinin, hindi siya nakatanggap ng mansyon, kundi isang banga na hindi naubusan. Ang pagtustos ng Diyos ay madalas \"sakto lang, sakto sa oras,\" para patuloy tayong tumingin sa Kanya."
      ),
    ],
    life: [
      t(
        "Aling Nena runs a sari-sari store in Cavite. Some weeks the sales are slow and the suppliers want payment. She has a habit: every morning, before opening the store, she prays the Lord's Prayer slowly and stops at \"daily bread.\" She tells her grandchildren, \"Hindi tayo pinangakuan ng sobra, pero kailanman hindi tayo pinabayaan.\" In thirty years she has seen hard days, but she can point to a hundred times God provided: a customer paying an old debt, a church gift, a neighbor's rice. Her testimony is not wealth; it is faithfulness.",
        "May sari-sari store si Aling Nena sa Cavite. May mga linggong mahina ang benta at sinisingil na siya ng supplier. May gawi siya: tuwing umaga, bago buksan ang tindahan, dahan-dahan niyang ipinapanalangin ang Ama Namin at humihinto sa \"kakanin sa araw-araw.\" Sabi niya sa mga apo niya, \"Hindi tayo pinangakuan ng sobra, pero kailanman hindi tayo pinabayaan.\" Sa tatlumpung taon, nakaranas siya ng mahihirap na araw, pero kaya niyang ituro ang isandaang pagkakataon na naglaan ang Diyos: isang suking nagbayad ng lumang utang, regalo mula sa simbahan, bigas mula sa kapitbahay. Ang patotoo niya ay hindi kayamanan; ito ay katapatan."
      ),
      t(
        "For OFW families, the padala can quietly become the provider in the family's eyes. Children say, \"Si Papa ang bumubuhay sa amin.\" But the paycheck is a channel, not the source. When the contract ends or the employer delays salary, families who know God as Provider will not collapse. Teach your household to thank God, not only the remittance center.",
        "Sa mga pamilyang OFW, tahimik na nagiging tagapaglaan ang padala sa mata ng pamilya. Sabi ng mga anak, \"Si Papa ang bumubuhay sa amin.\" Pero daluyan ang sahod, hindi pinagmumulan. Kapag natapos ang kontrata o naantala ang sahod, hindi babagsak ang pamilyang kilala ang Diyos bilang Tagapaglaan. Turuan ang inyong sambahayan na pasalamatan ang Diyos, hindi lang ang remittance center."
      ),
    ],
    twist: t(
      "We think God's provision is proven by full barns. But in the wilderness, the proof was a daily miracle that could not be stored. The manna that rotted overnight was God's loving way of saying, \"Trust Me again tomorrow.\" Your daily dependence is not a sign that God is stingy; it is a sign that He wants a daily relationship. A Father who gave everything at once might never hear from His children again.",
      "Akala natin, napapatunayan ang pagtustos ng Diyos sa punong kamalig. Pero sa ilang, ang patunay ay araw-araw na himalang hindi maiimbak. Ang manang nabulok sa magdamag ay mapagmahal na paraan ng Diyos para sabihing, \"Magtiwala ka ulit sa Akin bukas.\" Ang araw-araw mong pag-asa sa Kanya ay hindi tanda na kuripot ang Diyos; tanda ito na gusto Niya ng araw-araw na relasyon. Ang Amang nagbigay ng lahat nang minsanan ay baka hindi na marinig muli ang mga anak Niya."
    ),
    confirm: [
      t("Psalm 37:25: David had never seen the righteous forsaken or his children begging bread.", "Awit 37:25: hindi pa nakita ni David na pinabayaan ang matuwid o namalimos ng tinapay ang mga anak niya."),
      t("1 Kings 17:2-6: ravens brought Elijah bread and meat by the brook.", "1 Hari 17:2-6: dinalhan ng mga uwak si Elias ng tinapay at karne sa tabi ng batis."),
      t("Matthew 14:13-21: Jesus multiplied five loaves and two fish for thousands.", "Mateo 14:13-21: pinarami ni Hesus ang limang tinapay at dalawang isda para sa libu-libo."),
      t("2 Corinthians 9:8: God is able to make all grace abound so you have all sufficiency.", "2 Corinto 9:8: kayang pasaganain ng Diyos ang lahat ng biyaya para magkaroon kayo ng lahat ng sapat."),
    ],
    heart: [
      t(
        "Shift your trust from the channel to the Source. Work hard and save wisely, but rest your heart on God, not on the payslip.",
        "Ilipat ang pagtitiwala mula sa daluyan tungo sa Pinagmumulan. Magsipag at mag-ipon nang matalino, pero ipahinga ang puso mo sa Diyos, hindi sa payslip."
      ),
      t(
        "Cultivate gratitude for \"enough.\" A thankful heart sees provision where a greedy heart only sees what is missing.",
        "Linangin ang pasasalamat sa \"sapat.\" Nakikita ng pusong mapagpasalamat ang paglalaan kung saan ang nakikita lang ng pusong sakim ay ang kulang."
      ),
    ],
    questions: [
      t("Who or what do you really see as your provider: God, your job, your family abroad?", "Sino o ano ang talagang nakikita mong tagapaglaan mo: ang Diyos, ang trabaho mo, ang pamilya mo sa abroad?"),
      t("Can you name three specific times God provided for you \"just in time\"?", "Kaya mo bang pangalanan ang tatlong tiyak na pagkakataong naglaan ang Diyos para sa iyo nang \"sakto sa oras\"?"),
      t("Are you asking God for needs or mostly for wants?", "Ang hinihingi mo ba sa Diyos ay mga pangangailangan o kadalasan ay mga gusto?"),
      t("Is God asking you, like the widow, to trust Him with something you are holding tightly?", "Hinihiling ba ng Diyos, gaya ng sa balo, na ipagkatiwala mo sa Kanya ang isang bagay na mahigpit mong hawak?"),
    ],
    actions: [
      t("Start a \"provision journal\": write each way God provides this week, big or small.", "Magsimula ng \"journal ng paglalaan\": isulat ang bawat paraan ng paglalaan ng Diyos ngayong linggo, malaki man o maliit."),
      t("Pray \"Give us this day our daily bread\" slowly every morning, naming today's needs.", "Ipanalangin nang dahan-dahan tuwing umaga ang \"Bigyan Mo kami ngayon ng aming kakanin,\" at pangalanan ang mga kailangan ngayon."),
      t("When the padala or salary arrives, pray together as a family and thank God first.", "Pagdating ng padala o sahod, manalangin nang sama-sama bilang pamilya at pasalamatan muna ang Diyos."),
    ],
    prayer: t(
      "Jehovah Jireh, You are the Lord who provides. Thank You for every meal, every salary and every unexpected help You have sent. Forgive me for trusting my job or my savings more than You. Give me today my daily bread, and teach me to depend on You each morning. Help me work faithfully, give freely, and rest in Your care, knowing You will supply every need in Christ. In Jesus' name, Amen.",
      "Jehovah Jireh, Ikaw ang Panginoong naglalaan. Salamat sa bawat pagkain, bawat sahod at bawat di-inaasahang tulong na ipinadala Mo. Patawarin Mo ako sa pagtitiwala sa trabaho o ipon ko nang higit sa Iyo. Ibigay Mo sa akin ngayon ang aking kakanin, at turuan Mo akong umasa sa Iyo tuwing umaga. Tulungan Mo akong magtrabaho nang tapat, magbigay nang bukas-palad, at magpahinga sa pag-aalaga Mo, alam na ibibigay Mo ang lahat ng kailangan ko kay Cristo. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-contentment": {
    revelation: t(
      "Contentment is not getting everything you want; it is discovering that in Christ you already have everything you need.",
      "Ang kasiyahan ay hindi pagkuha ng lahat ng gusto mo; ito ay pagtuklas na kay Cristo, nasa iyo na ang lahat ng kailangan mo."
    ),
    mainTruth: t(
      "Paul says, \"I have learned in whatever situation I am to be content... I have learned the secret of facing plenty and hunger\" (Philippians 4:11-12). Hebrews 13:5 gives the reason: \"Keep your life free from love of money, and be content with what you have, for He has said, 'I will never leave you nor forsake you.'\" Ecclesiastes warns, \"He who loves money will not be satisfied with money\" (5:10). The tenth commandment forbids coveting (Exodus 20:17). Jesus told of a rich fool who built bigger barns and died that night, not rich toward God (Luke 12:13-21). David sang, \"The Lord is my chosen portion... the lines have fallen for me in pleasant places\" (Psalm 16:5-6).",
      "Sabi ni Pablo, \"Natutunan kong maging kontento sa anumang kalagayan... natutunan ko ang lihim ng pagharap sa kasaganaan at gutom\" (Filipos 4:11-12). Ibinibigay ng Hebreo 13:5 ang dahilan: \"Ilayo ninyo ang buhay ninyo sa pag-ibig sa salapi, at maging kontento sa kung ano ang mayroon kayo, sapagkat sinabi Niya, 'Hindi kita iiwan ni pababayaan man.'\" Nagbababala ang Eclesiastes, \"Ang umiibig sa salapi ay hindi masisiyahan sa salapi\" (5:10). Ipinagbabawal ng ikasampung utos ang pag-iimbot (Exodo 20:17). Ikinuwento ni Hesus ang mayamang hangal na nagtayo ng mas malalaking kamalig at namatay nang gabi ring iyon, hindi mayaman sa Diyos (Lucas 12:13-21). Umawit si David, \"Ang Panginoon ang aking piniling bahagi... napunta sa akin ang magagandang lupain\" (Awit 16:5-6)."
    ),
    insight: [
      t(
        "Paul uses the word \"learned\" twice. Contentment is not a personality type; it is a skill trained by the Holy Spirit through real seasons of plenty and want. Nobody is born content. That means there is hope for the person who always wants more: you can be taught. And contentment is not laziness or lack of ambition. Paul worked hard with his hands and planned missions. He simply refused to let his joy depend on his circumstances.",
        "Dalawang beses ginamit ni Pablo ang salitang \"natutunan.\" Ang kasiyahan ay hindi uri ng personalidad; ito ay kasanayang sinasanay ng Banal na Espiritu sa totoong mga panahon ng kasaganaan at kakulangan. Walang ipinanganak na kontento. Ibig sabihin, may pag-asa para sa taong laging naghahangad ng higit: puwede kang turuan. At ang kasiyahan ay hindi katamaran o kawalan ng pangarap. Nagtrabaho nang husto si Pablo gamit ang sariling kamay at nagplano ng mga misyon. Tumanggi lang siyang hayaang nakadepende sa kalagayan ang kagalakan niya."
      ),
      t(
        "Hebrews 13:5 connects contentment to God's presence, not to our possessions. The reason to be content is not \"you have enough stuff\" but \"you have Him.\" Discontent is often a symptom of a deeper hunger that money can never fill. We try to satisfy an eternal longing with temporary things, and then wonder why the new phone feels old in a month.",
        "Iniuugnay ng Hebreo 13:5 ang kasiyahan sa presensya ng Diyos, hindi sa mga ari-arian natin. Ang dahilan para maging kontento ay hindi \"sapat na ang gamit mo\" kundi \"nasa iyo Siya.\" Ang pagkayamot ay madalas sintomas ng mas malalim na gutom na hindi kailanman mapupunan ng pera. Sinusubukan nating busugin ang walang-hanggang pananabik ng mga panandaliang bagay, saka nagtataka kung bakit luma na ang pakiramdam sa bagong cellphone pagkalipas ng isang buwan."
      ),
    ],
    life: [
      t(
        "Social media has made coveting easier than ever. In one scroll you see a cousin's new car, a batchmate's trip to Japan, a co-worker's balikbayan box full of branded goods. Before you open the app, you were grateful; ten minutes later, you feel poor. Grace, a domestic helper in Hong Kong, noticed this pattern. She started a simple rule: for every post that made her envious, she wrote down one blessing God had given her. In a month her phone time dropped, and her joy rose. Nothing in her bank account changed; something in her heart did.",
        "Pinadali ng social media ang pag-iimbot nang higit kailanman. Sa isang scroll, makikita mo ang bagong kotse ng pinsan, ang biyahe ng batchmate sa Japan, ang balikbayan box ng katrabaho na puno ng branded. Bago mo buksan ang app, mapagpasalamat ka; pagkalipas ng sampung minuto, pakiramdam mo mahirap ka. Napansin ito ni Grace, isang domestic helper sa Hong Kong. Nagsimula siya ng simpleng patakaran: sa bawat post na nagpainggit sa kanya, isusulat niya ang isang pagpapalang ibinigay ng Diyos sa kanya. Sa loob ng isang buwan, bumaba ang oras niya sa cellphone, at tumaas ang kagalakan niya. Walang nagbago sa bank account niya; may nagbago sa puso niya."
      ),
      t(
        "For many OFWs, \"one more contract\" becomes ten more years. There is nothing wrong with working abroad for your family. But ask honestly: is the goal clear, or does it keep moving? Without contentment, there is no finish line. Some families have lost a father to a desert job not because they needed more but because they never decided what was enough.",
        "Para sa maraming OFW, ang \"isa pang kontrata\" ay nagiging sampung taon pa. Walang masama sa pagtatrabaho sa abroad para sa pamilya. Pero tanungin nang tapat: malinaw ba ang layunin, o patuloy itong gumagalaw? Kung walang kasiyahan, walang finish line. May mga pamilyang nawalan ng ama sa trabaho sa disyerto hindi dahil kailangan nila ng higit kundi dahil hindi nila kailanman napagpasyahan kung ano ang sapat."
      ),
    ],
    twist: t(
      "The rich fool's problem was not that he planned or saved; it was that he talked only to himself: \"I will say to my soul, 'Soul, you have ample goods'\" (Luke 12:19). He never once said \"God\" or \"neighbor.\" Discontent and greed are lonely. Contentment is surprisingly social: it frees you to enjoy God and to share with others. The person who has \"enough\" is the one who finally has room to give.",
      "Ang problema ng mayamang hangal ay hindi ang pagpaplano o pag-iipon niya; ang problema ay sarili lang ang kinakausap niya: \"Sasabihin ko sa aking kaluluwa, 'Kaluluwa, marami kang ari-arian'\" (Lucas 12:19). Kahit minsan hindi niya binanggit ang \"Diyos\" o ang \"kapwa.\" Malungkot ang pagkayamot at kasakiman. Ang kasiyahan ay nakakagulat na palakaibigan: pinalalaya ka nitong magalak sa Diyos at magbahagi sa iba. Ang taong may \"sapat\" ang siyang sa wakas ay may puwang para magbigay."
    ),
    confirm: [
      t("1 Timothy 6:7-8: we brought nothing into the world; with food and clothing we will be content.", "1 Timoteo 6:7-8: wala tayong dinala sa mundo; kung may pagkain at damit, kontento na tayo."),
      t("Psalm 23:1: \"The Lord is my shepherd; I shall not want.\"", "Awit 23:1: \"Ang Panginoon ang aking pastol; hindi ako magkukulang.\""),
      t("Genesis 3:6: the first sin began with wanting what God had withheld.", "Genesis 3:6: nagsimula ang unang kasalanan sa paghahangad sa ipinagkait ng Diyos."),
      t("Proverbs 15:16: better a little with the fear of the Lord than great treasure with trouble.", "Kawikaan 15:16: mas mabuti ang kaunti na may takot sa Panginoon kaysa malaking kayamanan na may gulo."),
    ],
    heart: [
      t(
        "Practice gratitude daily until it becomes your first reaction. Thankfulness is the antidote to comparison.",
        "Sanayin ang pasasalamat araw-araw hanggang ito na ang una mong reaksyon. Ang pasasalamat ang lunas sa pagkukumpara."
      ),
      t(
        "Decide what \"enough\" is for your family, write it down, and let God's presence, not the next purchase, be your security.",
        "Pagpasyahan kung ano ang \"sapat\" para sa pamilya mo, isulat ito, at hayaang ang presensya ng Diyos, hindi ang susunod na bibilhin, ang maging seguridad mo."
      ),
    ],
    questions: [
      t("What do you most often find yourself wanting that others have?", "Ano ang madalas mong hinahangad na mayroon ang iba?"),
      t("How does social media affect your contentment? Be honest.", "Paano naaapektuhan ng social media ang kasiyahan mo? Maging tapat."),
      t("Have you and your family defined what \"enough\" means? What is it?", "Napagpasyahan na ba ninyo ng pamilya mo kung ano ang ibig sabihin ng \"sapat\"? Ano ito?"),
      t("In what way is God Himself your \"portion\" right now?", "Sa anong paraan ang Diyos mismo ang iyong \"bahagi\" ngayon?"),
    ],
    actions: [
      t("Write ten things you are thankful for tonight, and read them aloud to God.", "Isulat ngayong gabi ang sampung bagay na ipinagpapasalamat mo, at basahin ang mga ito nang malakas sa Diyos."),
      t("Take a three-day break from the app that most stirs envy in you.", "Magpahinga nang tatlong araw sa app na pinakanagpapainggit sa iyo."),
      t("Sit down with your family (or call them) and write a simple \"enough\" goal for your savings and your time abroad.", "Umupo kasama ang pamilya mo (o tawagan sila) at isulat ang simpleng layuning \"sapat\" para sa ipon ninyo at sa panahon mo sa abroad."),
    ],
    prayer: t(
      "Lord, You are my portion and my cup. Forgive me for comparing, coveting and always wanting more. Teach me the secret Paul learned: to be content in plenty and in want because I have You. Thank You that You will never leave me nor forsake me. Fill the empty places in my heart that I have tried to fill with things. Make me rich toward You and generous toward others. In Jesus' name, Amen.",
      "Panginoon, Ikaw ang aking bahagi at aking saro. Patawarin Mo ako sa pagkukumpara, pag-iimbot at laging paghahangad ng higit. Turuan Mo ako ng lihim na natutunan ni Pablo: maging kontento sa kasaganaan at kakulangan dahil nasa akin Ka. Salamat dahil hindi Mo ako iiwan ni pababayaan man. Punuin Mo ang mga bakanteng bahagi ng puso ko na sinubukan kong punuin ng mga bagay. Gawin Mo akong mayaman sa Iyo at bukas-palad sa iba. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-generosity": {
    revelation: t(
      "Generosity is not what you do after you have enough; it is how you show that God is enough.",
      "Ang pagkabukas-palad ay hindi ginagawa kapag sapat na ang mayroon ka; ito ang paraan ng pagpapakitang sapat na ang Diyos."
    ),
    mainTruth: t(
      "The Macedonian churches, in \"extreme poverty,\" overflowed in generosity and \"gave themselves first to the Lord\" (2 Corinthians 8:1-5). Paul pointed to Jesus: \"Though He was rich, yet for your sake He became poor, so that you by His poverty might become rich\" (8:9). \"Each one must give as he has decided in his heart, not reluctantly or under compulsion, for God loves a cheerful giver\" (9:7). Proverbs says, \"One gives freely, yet grows all the richer\" (11:24-25). Jesus said, \"It is more blessed to give than to receive\" (Acts 20:35), and praised a widow who gave \"everything she had\" (Mark 12:41-44). Malachi 3:8-10 called Israel back to honoring God with the first and best.",
      "Ang mga iglesya sa Macedonia, sa gitna ng \"matinding kahirapan,\" ay umapaw sa pagkabukas-palad at \"ibinigay muna ang kanilang sarili sa Panginoon\" (2 Corinto 8:1-5). Itinuro ni Pablo si Hesus: \"Kahit Siya ay mayaman, naging dukha Siya alang-alang sa inyo, upang sa pamamagitan ng Kanyang pagiging dukha ay maging mayaman kayo\" (8:9). \"Magbigay ang bawat isa ayon sa ipinasya ng kanyang puso, hindi nang may pag-aatubili o pamimilit, sapagkat iniibig ng Diyos ang nagbibigay nang masaya\" (9:7). Sabi ng Kawikaan, \"May nagbibigay nang maluwag, pero lalo pang yumayaman\" (11:24-25). Sinabi ni Hesus, \"Higit na pinagpala ang nagbibigay kaysa tumatanggap\" (Gawa 20:35), at pinuri Niya ang balong nagbigay ng \"lahat ng mayroon siya\" (Marcos 12:41-44). Tinawag ng Malakias 3:8-10 ang Israel pabalik sa paggalang sa Diyos gamit ang una at pinakamabuti."
    ),
    insight: [
      t(
        "Many teachers misuse 2 Corinthians 9 and Malachi 3 as investment formulas: \"Sow a thousand, reap ten thousand.\" But Paul says the harvest is so that \"you may abound in every good work\" and that thanksgiving will overflow to God (9:8, 11-12). God enriches the giver \"to be generous in every way,\" not to be rich for himself. Giving is not a way to manipulate God; it is a response to a God who already gave His Son. Christians differ on whether the tithe is a requirement today, but all agree that giving should be regular, proportionate, cheerful and first, not leftover.",
        "Maraming tagapagturo ang maling gumagamit ng 2 Corinto 9 at Malakias 3 bilang pormula ng pamumuhunan: \"Magtanim ng isang libo, mag-ani ng sampung libo.\" Pero sabi ni Pablo, ang ani ay para \"sumagana kayo sa bawat mabuting gawa\" at para umapaw ang pasasalamat sa Diyos (9:8, 11-12). Pinayayaman ng Diyos ang nagbibigay \"para maging bukas-palad sa lahat ng paraan,\" hindi para yumaman para sa sarili. Ang pagbibigay ay hindi paraan para manipulahin ang Diyos; ito ay tugon sa Diyos na nagbigay na ng Kanyang Anak. Magkakaiba ang pananaw ng mga Kristiyano kung obligasyon pa ba ngayon ang ikapu, pero lahat ay sang-ayon na ang pagbibigay ay dapat regular, ayon sa kakayahan, masaya at inuuna, hindi tira-tira."
      ),
      t(
        "Notice the order in 2 Corinthians 8:5: \"they gave themselves first to the Lord.\" Generosity begins with surrender, not with a wallet. When God owns your heart, your money follows. When He does not, even large gifts can be about image, control or guilt.",
        "Pansinin ang pagkakasunod sa 2 Corinto 8:5: \"ibinigay muna nila ang kanilang sarili sa Panginoon.\" Nagsisimula ang pagkabukas-palad sa pagsuko, hindi sa pitaka. Kapag pag-aari ng Diyos ang puso mo, sumusunod ang pera mo. Kapag hindi, kahit malalaking regalo ay puwedeng tungkol sa imahe, kontrol o pakiramdam ng pagkakasala."
      ),
    ],
    life: [
      t(
        "Filipinos are naturally generous: we share our ulam with neighbors and send money to relatives. But for many OFWs, generosity has turned into pressure. Every call is a request; every vacation is a list of pasalubong and loans that are never repaid. Biblical generosity is cheerful and \"decided in the heart,\" not squeezed out by guilt. Jessa, a factory worker in Taiwan, prayed and made a plan: a fixed amount for her church, a fixed amount for her parents, a fixed emergency fund for relatives, and savings for her own future. Saying \"this is what I can give\" felt hard at first. But her giving became joyful again, and her family learned to respect it.",
        "Likas na bukas-palad ang mga Pilipino: hinahatian natin ng ulam ang kapitbahay at pinapadalhan ng pera ang mga kamag-anak. Pero para sa maraming OFW, naging presyon na ang pagbibigay. Bawat tawag ay hiling; bawat bakasyon ay listahan ng pasalubong at utang na hindi na nababayaran. Ang biblikal na pagkabukas-palad ay masaya at \"ipinasya sa puso,\" hindi piniga ng konsensya. Si Jessa, isang factory worker sa Taiwan, ay nanalangin at gumawa ng plano: takdang halaga para sa simbahan niya, takdang halaga para sa mga magulang niya, takdang emergency fund para sa mga kamag-anak, at ipon para sa sarili niyang kinabukasan. Mahirap sa simula ang magsabing \"ito ang kaya kong ibigay.\" Pero muling naging masaya ang pagbibigay niya, at natutong igalang ito ng pamilya niya."
      ),
      t(
        "Generosity is not only money. It is time with a lonely kababayan, skills offered to the church, a meal for a sick neighbor, your attention for your children. The Macedonians had little money, but they gave themselves. You can always give something.",
        "Ang pagkabukas-palad ay hindi lang pera. Ito ay oras para sa nag-iisang kababayan, kasanayang iniaalay sa simbahan, pagkain para sa maysakit na kapitbahay, atensyon para sa mga anak mo. Kaunti ang pera ng mga taga-Macedonia, pero ibinigay nila ang kanilang sarili. Laging may maibibigay ka."
      ),
    ],
    twist: t(
      "Jesus sat \"opposite the treasury\" and watched how people gave (Mark 12:41). He was not impressed by the size of the gifts but by the cost. The widow's two coins outweighed the rich men's bags. Heaven's accounting is not \"How much did you give?\" but \"How much did you keep?\" A small gift from a sacrificial heart is a fortune in God's eyes, and a large gift that costs nothing may count for little.",
      "Umupo si Hesus \"sa tapat ng kabang-yaman\" at pinanood kung paano nagbibigay ang mga tao (Marcos 12:41). Hindi Siya humanga sa laki ng mga regalo kundi sa halaga ng isinakripisyo. Mas mabigat ang dalawang barya ng balo kaysa sa mga supot ng mayayaman. Ang kuwenta ng langit ay hindi \"Gaano karami ang ibinigay mo?\" kundi \"Gaano karami ang itinira mo?\" Ang maliit na regalo mula sa pusong nagsasakripisyo ay kayamanan sa mata ng Diyos, at ang malaking regalo na walang isinakripisyo ay maaaring kaunti lang ang halaga."
    ),
    confirm: [
      t("John 3:16: God so loved the world that He gave His only Son.", "Juan 3:16: gayon na lamang ang pag-ibig ng Diyos sa sanlibutan kaya ibinigay Niya ang Kanyang bugtong na Anak."),
      t("Acts 4:32-35: the early church shared so that no one among them was in need.", "Gawa 4:32-35: nagbahaginan ang unang iglesya kaya walang nangangailangan sa kanila."),
      t("Luke 19:8: Zacchaeus' encounter with Jesus turned a greedy man into a giver.", "Lucas 19:8: ang pakikipagtagpo ni Zaqueo kay Hesus ang nagpabago sa sakim na lalaki para maging mapagbigay."),
      t("Proverbs 3:9: honor the Lord with your wealth and the firstfruits of all your produce.", "Kawikaan 3:9: parangalan ang Panginoon ng iyong yaman at ng unang bunga ng iyong ani."),
    ],
    heart: [
      t(
        "Give first, not last. Set aside your giving when the salary arrives, before bills and wants compete for it.",
        "Magbigay nang una, hindi huli. Itabi ang ibibigay mo pagdating ng sahod, bago pa mag-agawan ang mga bayarin at gusto."
      ),
      t(
        "Give cheerfully and wisely. Let love, not guilt or pressure, decide your giving, and let prayer set its limits.",
        "Magbigay nang masaya at matalino. Hayaang pag-ibig, hindi konsensya o presyon, ang magpasya sa pagbibigay mo, at hayaang panalangin ang magtakda ng hangganan nito."
      ),
    ],
    questions: [
      t("Is your giving planned and first, or leftover and occasional?", "Ang pagbibigay mo ba ay planado at inuuna, o tira-tira at paminsan-minsan?"),
      t("Do you give cheerfully, or mostly out of guilt or family pressure?", "Masaya ka bang nagbibigay, o kadalasan dahil sa konsensya o presyon ng pamilya?"),
      t("Have you ever been taught that giving is a way to get rich? How does this lesson correct it?", "Naturuan ka na bang ang pagbibigay ay paraan para yumaman? Paano ito itinutuwid ng araling ito?"),
      t("Beyond money, what can you give this week: time, skills, attention?", "Bukod sa pera, ano ang maibibigay mo ngayong linggo: oras, kasanayan, atensyon?"),
    ],
    actions: [
      t("Pray and decide a regular amount or percentage to give to God's work, and set it aside first on payday.", "Manalangin at magpasya ng regular na halaga o porsyento na ibibigay sa gawain ng Diyos, at itabi ito muna pagdating ng sahod."),
      t("Write a simple family support plan so your help to relatives is generous, planned and sustainable.", "Gumawa ng simpleng plano ng suporta sa pamilya para ang tulong mo sa mga kamag-anak ay bukas-palad, planado at kaya mong ituloy."),
      t("Do one secret act of generosity this week that no one will know about.", "Gumawa ng isang lihim na pagkabukas-palad ngayong linggo na walang makaaalam."),
    ],
    prayer: t(
      "Generous Father, You gave Your only Son for me. Everything I have came from Your hand. Forgive me for holding tightly what You gave freely, and for giving out of guilt instead of love. I give myself to You first. Make me a cheerful giver, wise and faithful with what You entrust to me. Let my giving point people to Jesus, who became poor so I could be rich in You. In His name, Amen.",
      "Mapagbigay na Ama, ibinigay Mo ang Iyong bugtong na Anak para sa akin. Ang lahat ng mayroon ako ay galing sa kamay Mo. Patawarin Mo ako sa mahigpit na paghawak sa ibinigay Mo nang libre, at sa pagbibigay dahil sa konsensya sa halip na pag-ibig. Ibinibigay ko muna ang aking sarili sa Iyo. Gawin Mo akong masayang nagbibigay, matalino at tapat sa ipinagkakatiwala Mo sa akin. Ituro nawa ng pagbibigay ko ang mga tao kay Hesus, na naging dukha para ako ay maging mayaman sa Iyo. Sa Kanyang pangalan, Amen."
    ),
  },
  "c-work-excellence": {
    revelation: t(
      "Your daily work is not a detour from your calling; it is the place where you worship, because you are really working for the Lord.",
      "Ang araw-araw mong trabaho ay hindi paglihis sa iyong tawag; ito ang lugar ng iyong pagsamba, dahil ang Panginoon talaga ang pinagsisilbihan mo."
    ),
    mainTruth: t(
      "Work existed before the Fall: God put Adam in the garden \"to work it and take care of it\" (Genesis 2:15). Work is therefore not a curse, though sin made it painful. Paul tells us, \"Whatever you do, work at it with all your heart, as working for the Lord, not for human masters, since you know that you will receive an inheritance from the Lord as a reward. It is the Lord Christ you are serving\" (Colossians 3:23-24). The boss on your payslip is not your final boss.",
      "Ang trabaho ay umiral bago pa ang pagkahulog: inilagay ng Diyos si Adan sa hardin \"upang bungkalin at ingatan ito\" (Genesis 2:15). Kaya hindi sumpa ang trabaho, bagaman ginawa itong mahirap ng kasalanan. Sabi ni Pablo, \"Anuman ang inyong gawin, gawin ninyo nang buong puso, na parang para sa Panginoon at hindi para sa tao... Si Cristong Panginoon ang inyong pinaglilingkuran\" (Colosas 3:23-24). Ang amo sa sahod mo ay hindi ang huling amo mo."
    ),
    insight: [
      t(
        "Many believers split life in two: Sunday is \"spiritual\" and Monday to Saturday is \"secular.\" That split quietly produces half-hearted workers who save their best energy for church activities. But Joseph was as anointed in Potiphar's kitchen and in prison paperwork as he later was in the palace, and Daniel was promoted because \"he was trustworthy and neither corrupt nor negligent\" (Daniel 6:4). His enemies searched for a flaw in his work and found none.",
        "Maraming mananampalataya ang hinahati ang buhay: ang Linggo ay \"espirituwal\" at ang Lunes hanggang Sabado ay \"makamundo.\" Tahimik nitong ginagawang pabaya ang manggagawa na ang pinakamagandang lakas ay itinatabi para sa gawain sa simbahan. Pero kasing-pinahiran si Jose sa kusina ni Potifar at sa papeles ng bilangguan gaya ng sa palasyo, at tumaas si Daniel dahil \"siya ay tapat at walang kapabayaan o katiwalian\" (Daniel 6:4). Naghanap ng mali sa trabaho niya ang mga kaaway niya at wala silang nakita."
      ),
      t(
        "Scripture warns against both extremes. The sluggard \"folds his hands to rest\" and poverty comes \"like a thief\" (Proverbs 6:10-11). Yet Paul also says, \"If anyone is not willing to work, let him not eat\" (2 Thessalonians 3:10), and he rebuked busybodies who would not earn their own bread. Excellence is not perfectionism or overwork; it is faithfulness, doing the task in front of you as if Jesus were the one inspecting it.",
        "Binabalaan tayo ng Kasulatan laban sa dalawang sukdulan. Ang tamad ay \"nagkukrus ng kamay para magpahinga\" at darating ang kahirapan \"na parang magnanakaw\" (Kawikaan 6:10-11). Pero sabi rin ni Pablo, \"Kung ang sinuman ay ayaw magtrabaho, huwag siyang kumain\" (2 Tesalonica 3:10), at sinaway niya ang mga pakialamero na ayaw kumita ng sariling kain. Ang kahusayan ay hindi pagiging perpekto o pagpapakamatay sa trabaho; ito ay katapatan, ginagawa ang nasa harap mo na parang si Hesus ang nag-iinspeksyon."
      ),
    ],
    life: [
      t(
        "Rosalie works as a caregiver for an elderly employer in Kuwait. Nobody sees her at 3 a.m. when she turns the patient and changes the sheets again. She could cut corners and no one would know. But she told her Bible study group, \"When I remember that I am serving Christ in this old man, even the night shift becomes an offering.\" Her employer's family, who are not believers, once asked, \"Why are you different?\" That was her pulpit.",
        "Si Rosalie ay caregiver ng isang matandang amo sa Kuwait. Walang nakakakita sa kanya nang alas-tres ng madaling-araw kapag binabaligtad niya ang pasyente at nagpapalit ng kumot. Puwede siyang magtipid sa gawa at walang makakaalam. Pero sabi niya sa Bible study nila, \"Kapag naaalala kong si Cristo ang pinaglilingkuran ko sa matandang ito, pati night shift ay nagiging alay.\" Minsan, tinanong siya ng pamilya ng amo niyang hindi mananampalataya, \"Bakit iba ka?\" Iyon ang kanyang pulpito."
      ),
      t(
        "Whether you drive a jeepney, run a sari-sari store, sit in an office or clean a hotel room, ask: \"Would I do this the same way if Jesus were the customer?\" Come on time. Keep your word. Refuse the shortcut that hurts someone. Do not gossip about the boss. Small, hidden faithfulness is how a witness is built.",
        "Nagmamaneho ka man ng jeepney, nagbabantay ng sari-sari store, nasa opisina o naglilinis ng kuwarto sa hotel, itanong mo: \"Ganito ko rin ba gagawin ito kung si Hesus ang kustomer?\" Pumasok nang maaga. Tuparin ang salita. Iwasan ang shortcut na makakasakit ng iba. Huwag magchismis tungkol sa amo. Sa maliit at lihim na katapatan itinatayo ang patotoo."
      ),
    ],
    twist: t(
      "We think we must escape the workplace to serve God \"full time.\" But Jesus spent about thirty years in ordinary life, working as a carpenter, before three years of public ministry. The Father declared Himself well pleased with His Son before a single miracle happened. In the Kingdom, faithfulness in the hidden place is not the waiting room for your calling; it is part of it.",
      "Akala natin kailangan nating umalis sa trabaho para maglingkod sa Diyos nang \"full time.\" Pero mga tatlumpung taon si Hesus sa ordinaryong buhay, karpintero, bago ang tatlong taon ng hayag na ministeryo. Sinabi na ng Ama na lugod na lugod Siya sa Kanyang Anak bago pa ang unang himala. Sa Kaharian, ang katapatan sa lihim na lugar ay hindi silid-hintayan ng tawag mo; bahagi na ito ng tawag."
    ),
    confirm: [
      t("Genesis 39:2-4: the Lord was with Joseph, and his master saw it in his work.", "Genesis 39:2-4: sumakanya ang Panginoon, at nakita ng kanyang amo sa kanyang trabaho."),
      t("Proverbs 22:29: the one skilled in work will stand before kings.", "Kawikaan 22:29: ang sanay sa gawain ay haharap sa mga hari."),
      t("Exodus 31:1-5: God filled Bezalel with His Spirit for craftsmanship.", "Exodo 31:1-5: pinuspos ng Diyos si Bezalel ng Kanyang Espiritu para sa husay sa paggawa."),
      t("Ephesians 4:28: work honestly so you have something to share with the needy.", "Efeso 4:28: magtrabaho nang tapat upang may maibahagi sa nangangailangan."),
    ],
    heart: [
      t(
        "Repent of half-heartedness. If you have been coasting, showing up late, wasting office hours or constantly complaining, bring it to Jesus and ask for a fresh heart for the work He has given you.",
        "Magsisi sa pagiging pabaya. Kung nagpapabaya ka, nahuhuli, nag-aaksaya ng oras o laging nagrereklamo, dalhin ito kay Hesus at humingi ng bagong puso para sa trabahong ibinigay Niya."
      ),
      t(
        "Let go of the idol of work too. Your worth is not your job title or your overtime. You work from rest in Christ, not to earn His love, and you keep a rhythm of rest for family and worship.",
        "Bitawan din ang diyus-diyosan ng trabaho. Ang halaga mo ay wala sa titulo o sa overtime. Nagtatrabaho ka mula sa kapahingahan kay Cristo, hindi para kitain ang Kanyang pag-ibig, at may ritmo ka ng pahinga para sa pamilya at pagsamba."
      ),
    ],
    questions: [
      t("Do I work differently when no one is watching? What does that reveal about who I am really working for?", "Iba ba ang paraan ng trabaho ko kapag walang nakatingin? Ano ang sinasabi nito kung para kanino talaga ako nagtatrabaho?"),
      t("Where have I cut corners or wasted time that I need to make right?", "Saan ako nagtipid sa gawa o nag-aksaya ng oras na kailangan kong ituwid?"),
      t("Has work become my identity or my idol, crowding out God and family?", "Naging pagkakakilanlan ko o diyus-diyosan na ba ang trabaho, na tumutulak sa Diyos at pamilya?"),
      t("What would my coworkers say about the way I work and speak?", "Ano ang masasabi ng mga katrabaho ko sa paraan ng aking pagtatrabaho at pananalita?"),
    ],
    actions: [
      t("Tomorrow morning, dedicate your workday to Jesus in one sentence of prayer before you start.", "Bukas ng umaga, ialay mo kay Hesus ang buong araw mo sa isang maikling panalangin bago magsimula."),
      t("Choose one task you usually rush or avoid and do it with full excellence this week.", "Pumili ng isang gawain na madalas mong minamadali o iniiwasan at gawin ito nang buong husay ngayong linggo."),
      t("Quietly bless one coworker or your employer: a kind word, help with a task or a prayer for them.", "Tahimik na pagpalain ang isang katrabaho o ang amo mo: mabuting salita, tulong sa gawain o panalangin para sa kanila."),
    ],
    prayer: t(
      "Lord Jesus, thank You that my work matters to You. Forgive me for the times I worked for applause, for money or out of laziness. Teach me to serve You in every task, seen or unseen. Give me skill, honesty and joy, and let my coworkers see You in how I work. Keep me from making work my god, and bring me to rest in Your love. Be glorified in my Monday as much as my Sunday. In Your name I pray, Amen.",
      "Panginoong Hesus, salamat po na mahalaga sa Inyo ang aking trabaho. Patawarin Mo ako sa mga panahong nagtrabaho ako para sa palakpak, sa pera o dahil sa katamaran. Turuan Mo akong maglingkod sa Iyo sa bawat gawain, nakikita man o hindi. Bigyan Mo ako ng husay, katapatan at galak, at hayaang makita Ka ng mga katrabaho ko sa paraan ng paggawa ko. Ilayo Mo akong gawing diyos ang trabaho, at dalhin Mo ako sa kapahingahan sa Iyong pag-ibig. Maluwalhati Ka sa Lunes ko gaya ng sa Linggo ko. Sa Iyong pangalan, Amen."
    ),
  },
  "c-financial-stewardship": {
    revelation: t(
      "Nothing in your wallet is truly yours; you are a manager of God's money, and how you handle small amounts reveals whether He can trust you with true riches.",
      "Walang laman ang wallet mo na tunay na iyo; tagapamahala ka ng pera ng Diyos, at ang paghawak mo sa maliit ay nagpapakita kung mapagkakatiwalaan ka Niya sa tunay na kayamanan."
    ),
    mainTruth: t(
      "\"The earth is the Lord's, and everything in it\" (Psalm 24:1). If God is owner, we are stewards, and a steward is judged by faithfulness, not by size. Jesus said, \"Whoever can be trusted with very little can also be trusted with much\" (Luke 16:10), and \"You cannot serve both God and money\" (Luke 16:13). Money is a wonderful servant and a terrible master.",
      "\"Sa Panginoon ang lupa at ang lahat ng laman nito\" (Awit 24:1). Kung ang Diyos ang may-ari, tagapamahala tayo, at ang tagapamahala ay hinahatulan sa katapatan, hindi sa laki. Sabi ni Hesus, \"Ang tapat sa kaunti ay tapat din sa marami\" (Lucas 16:10), at \"Hindi kayo maaaring maglingkod sa Diyos at sa salapi\" (Lucas 16:13). Ang pera ay mahusay na alipin pero kakila-kilabot na panginoon."
    ),
    insight: [
      t(
        "Many believers think finances are \"unspiritual,\" so they pray about money only in emergencies. Yet Jesus spoke about money constantly, because money shows what we really trust. Notice that Luke 16 links money to \"true riches.\" The way you handle a small paycheck is the Father's training ground for greater responsibility.",
        "Maraming mananampalataya ang nag-iisip na \"hindi espirituwal\" ang pera, kaya sa emergency lang sila nagdarasal tungkol dito. Pero madalas pag-usapan ni Hesus ang pera dahil ipinapakita nito kung saan talaga tayo nagtitiwala. Pansinin na iniuugnay ng Lucas 16 ang pera sa \"tunay na kayamanan.\" Ang paghawak mo sa maliit na sahod ay pagsasanay ng Ama para sa mas malaking responsibilidad."
      ),
      t(
        "The Bible gives plain wisdom: \"The wise store up choice food and olive oil, but fools gulp theirs down\" (Proverbs 21:20). \"The borrower is slave to the lender\" (Proverbs 22:7). Count the cost before you build (Luke 14:28-30). And provide for your family: whoever does not do so \"has denied the faith\" (1 Timothy 5:8). Planning is not lack of faith; it is obedience.",
        "May payak na karunungan ang Biblia: \"Ang marunong ay nag-iimpok ng piling pagkain at langis, ngunit nilulunok ito ng mangmang\" (Kawikaan 21:20). \"Ang umuutang ay alipin ng nagpapautang\" (Kawikaan 22:7). Bilangin ang gastos bago magtayo (Lucas 14:28-30). At buhayin ang pamilya: ang hindi gumagawa nito ay \"itinakwil na ang pananampalataya\" (1 Timoteo 5:8). Hindi kakulangan ng pananampalataya ang pagpaplano; pagsunod ito."
      ),
    ],
    life: [
      t(
        "Ben, an OFW in Dubai, earned well but his family back home was always short. Every payday he sent money, then spent the rest on gadgets and loans for relatives. After a friend taught him to write a simple budget, he set aside his giving first, then savings, then remittance, and the rest for living. In a year he had an emergency fund and had paid off a debt. \"I did not earn more,\" he said. \"I just started managing it like it was God's.\"",
        "Si Ben, OFW sa Dubai, malaki ang kita pero laging kapos ang pamilya niya sa Pilipinas. Tuwing sahod, magpapadala siya, tapos uubusin ang natira sa gadgets at pautang sa kamag-anak. Nang turuan siya ng kaibigan na gumawa ng simpleng budget, inuna niya ang pagbibigay, saka ipon, saka padala, at ang natira ay para sa gastusin. Sa isang taon, may emergency fund na siya at nabayaran ang isang utang. \"Hindi tumaas ang kita ko,\" sabi niya. \"Nagsimula lang akong mamahala na parang pera ng Diyos ito.\""
      ),
      t(
        "Start where you are: write down income and expenses, give first, save something even if small, avoid loans for wants, and pay debts steadily. If you are drowning, talk with a trusted pastor or mature believer. Stewardship is not about being rich; it is about being faithful and free.",
        "Magsimula kung nasaan ka: isulat ang kita at gastos, magbigay muna, mag-ipon kahit maliit, iwasan ang utang para sa luho, at bayaran nang tuloy-tuloy ang mga utang. Kung nalulunod ka na, kausapin ang pinagkakatiwalaang pastor o maturing mananampalataya. Hindi tungkol sa pagyaman ang pamamahala; tungkol ito sa katapatan at kalayaan."
      ),
    ],
    twist: t(
      "We think a budget is a cage that limits our freedom. In the Kingdom, it is the opposite: a plan is how you say yes to what matters most. Jesus' story of the faithful servant shows that the reward for good management is not retirement but more responsibility and the master's joy (Matthew 25:21). Faithfulness with money is training for sharing in Christ's rule.",
      "Akala natin ang budget ay hawla na naglilimita sa kalayaan. Sa Kaharian, kabaligtaran: ang plano ang paraan ng pagsabi ng oo sa pinakamahalaga. Ipinakikita ng talinghaga ni Hesus tungkol sa tapat na alipin na ang gantimpala ng mahusay na pamamahala ay hindi pagreretiro kundi mas malaking responsibilidad at kagalakan ng panginoon (Mateo 25:21). Ang katapatan sa pera ay pagsasanay sa pakikibahagi sa paghahari ni Cristo."
    ),
    confirm: [
      t("Matthew 25:14-30: the servants were judged by faithfulness with what the master gave.", "Mateo 25:14-30: hinatulan ang mga alipin sa katapatan sa ibinigay ng panginoon."),
      t("Proverbs 3:9-10: honor the Lord with your wealth and the firstfruits of your income.", "Kawikaan 3:9-10: parangalan ang Panginoon ng iyong kayamanan at unang bunga ng iyong kita."),
      t("Romans 13:8: owe no one anything except to love one another.", "Roma 13:8: huwag magkautang kaninuman maliban sa pag-ibig sa isa't isa."),
      t("Proverbs 21:5: the plans of the diligent lead to plenty.", "Kawikaan 21:5: ang plano ng masipag ay humahantong sa kasaganaan."),
    ],
    heart: [
      t(
        "Confess any hidden spending, careless habits or fear about money. Bring your whole financial picture into the light of God's wisdom and, where needed, a trusted mentor.",
        "Ipagtapat ang anumang lihim na paggastos, pabayang gawi o takot tungkol sa pera. Dalhin ang buong larawan ng pananalapi mo sa liwanag ng karunungan ng Diyos at, kung kailangan, sa pinagkakatiwalaang tagapayo."
      ),
      t(
        "Choose to be a manager, not an owner. Hold things loosely, give cheerfully, and trust that the One who owns it all will supply what you need.",
        "Piliing maging tagapamahala, hindi may-ari. Humawak nang maluwag, magbigay nang masaya, at magtiwalang ang may-ari ng lahat ang magtutustos ng kailangan mo."
      ),
    ],
    questions: [
      t("If I looked at my bank statement, would it show that I belong to Jesus or to my wants?", "Kung titingnan ang bank statement ko, ipapakita ba nitong kay Hesus ako o sa mga luho ko?"),
      t("Do I know where my money goes each month?", "Alam ko ba kung saan napupunta ang pera ko bawat buwan?"),
      t("Is there a debt or financial habit I am hiding from my spouse, family or God?", "May utang o gawi sa pera ba akong itinatago sa asawa, pamilya o sa Diyos?"),
      t("Am I generous and wise, or only one of the two?", "Mapagbigay at marunong ba ako, o isa lang sa dalawa?"),
    ],
    actions: [
      t("Write a simple monthly budget this week: income, giving, savings, remittance, needs.", "Gumawa ng simpleng buwanang budget ngayong linggo: kita, handog, ipon, padala, pangangailangan."),
      t("List your debts and choose one to pay down first; set a date.", "Ilista ang mga utang at pumili ng uunahing bayaran; magtakda ng petsa."),
      t("Dedicate your finances to God in prayer and ask Him for wisdom for one pending money decision.", "Ialay sa Diyos sa panalangin ang pananalapi mo at humingi ng karunungan sa isang nakabinbing desisyon tungkol sa pera."),
    ],
    prayer: t(
      "Father, everything I have is from You and belongs to You. Forgive me for careless spending, hidden debts and fear about tomorrow. Teach me to be faithful with little so You can trust me with more. Give me wisdom to plan, discipline to save, courage to give, and honesty with my family. Free me from the slavery of debt and the love of money. Let my wallet say that Jesus is Lord. In His name, Amen.",
      "Ama, lahat ng mayroon ako ay galing at pag-aari Mo. Patawarin Mo ako sa pabayang paggastos, nakatagong utang at takot sa bukas. Turuan Mo akong maging tapat sa kaunti para mapagkatiwalaan Mo ako ng higit pa. Bigyan Mo ako ng karunungang magplano, disiplinang mag-ipon, tapang na magbigay at katapatan sa pamilya ko. Palayain Mo ako sa pagkaalipin ng utang at pag-ibig sa salapi. Hayaang sabihin ng wallet ko na Panginoon si Hesus. Sa Kanyang pangalan, Amen."
    ),
  },
  "c-avoiding-greed": {
    revelation: t(
      "Greed is not about how much you have; it is about what has you, and Jesus warns that a life is never measured by its possessions.",
      "Ang kasakiman ay hindi tungkol sa dami ng mayroon ka; tungkol ito sa kung ano ang may hawak sa iyo, at nagbababala si Hesus na ang buhay ay hindi nasusukat sa dami ng ari-arian."
    ),
    mainTruth: t(
      "\"Watch out! Be on your guard against all kinds of greed; life does not consist in an abundance of possessions\" (Luke 12:15). Jesus told this to a man who wanted his share of an inheritance, and then told the story of a farmer who had a great harvest, built bigger barns and died that night, \"rich toward himself\" but not \"rich toward God\" (Luke 12:21). Paul calls greed \"idolatry\" (Colossians 3:5) because it gives to things the trust and devotion that belong to God alone.",
      "\"Mag-ingat kayo! Iwasan ninyo ang lahat ng uri ng kasakiman; ang buhay ng tao ay hindi nakasalalay sa dami ng kanyang ari-arian\" (Lucas 12:15). Sinabi ito ni Hesus sa isang lalaking gustong makuha ang bahagi niya sa mana, at isinalaysay Niya ang magsasakang nag-ani nang sagana, nagtayo ng mas malalaking kamalig at namatay nang gabing iyon, \"mayaman para sa sarili\" pero hindi \"mayaman sa Diyos\" (Lucas 12:21). Tinatawag ni Pablo na \"pagsamba sa diyus-diyosan\" ang kasakiman (Colosas 3:5) dahil ibinibigay nito sa mga bagay ang tiwala at debosyon na sa Diyos lamang."
    ),
    insight: [
      t(
        "Notice what the rich fool never said: not one mention of another person and not one mention of God. He talks to himself: \"What shall I do? I will do this, I will tear down, I will say to my soul.\" Greed shrinks the world to one person. It also hides itself as prudence, and the farmer's plan sounded sensible. That is why Jesus says, \"Be on your guard,\" because greed rarely feels like greed from the inside.",
        "Pansinin ang hindi sinabi ng mangmang na mayaman: walang binanggit na ibang tao at walang binanggit na Diyos. Kausap niya ang sarili: \"Ano ang gagawin ko? Gagawin ko ito, gigibain ko, sasabihin ko sa aking kaluluwa.\" Pinaliliit ng kasakiman ang mundo hanggang sa isang tao. Nagkukubli rin ito bilang pagiging maingat; makatwiran ang tunog ng plano ng magsasaka. Kaya sabi ni Hesus, \"Mag-ingat kayo,\" dahil bihirang maramdaman ang kasakiman bilang kasakiman kapag nasa loob ka nito."
      ),
      t(
        "Greed is not just a rich man's sin. Achan hid a robe and silver in his tent (Joshua 7:19-21) and brought trouble on a whole nation. The rich young ruler kept the commandments but could not release his grip, and \"went away sad\" (Mark 10:22). The poor can be as greedy as the wealthy, because greed is a heart that says \"never enough,\" and it can live in a one-room house as easily as in a mansion.",
        "Hindi lang kasalanan ng mayaman ang kasakiman. Itinago ni Acan ang balabal at pilak sa kanyang tolda (Josue 7:19-21) at nagdala ng kapahamakan sa buong bansa. Sinunod ng mayamang batang pinuno ang mga utos pero hindi mabitawan ang hawak niya at \"umalis na malungkot\" (Marcos 10:22). Ang mahirap ay puwedeng maging kasakim ng mayaman, dahil ang kasakiman ay pusong nagsasabing \"hindi pa sapat,\" at maaari itong tumira sa isang-kuwartong bahay gaya ng sa mansyon."
      ),
    ],
    life: [
      t(
        "Think of the pressure on OFWs: the family wants a bigger house, a newer phone, a car, and the lure of a quick loan or a risky investment promising double returns is everywhere. It is not wrong to want a better life for your children. But when work swallows every Sunday, when you stop calling home because you are too tired, when you borrow what you cannot repay, ask: who is in charge, the need or the craving?",
        "Isipin ang presyon sa mga OFW: gusto ng pamilya ang mas malaking bahay, mas bagong cellphone, sasakyan, at kahit saan may patibong ng mabilisang utang o mapanganib na investment na nangangakong doble ang balik. Hindi masama ang naisin ang mas magandang buhay para sa mga anak. Pero kapag nilamon na ng trabaho ang bawat Linggo, kapag hindi ka na tumatawag sa bahay dahil sa pagod, kapag umuutang ka ng hindi mo kayang bayaran, itanong: sino ang may hawak, ang pangangailangan o ang pagnanasa?"
      ),
      t(
        "A simple test: Do I give as easily as I gather? Can I say \"enough\"? Am I willing to let a purchase, a promotion or a deal go if it would cost my integrity or my time with God? Greed loses its grip every time we give something away deliberately.",
        "Isang simpleng pagsubok: Madali ba akong magbigay gaya ng pagkuha? Kaya ko bang sabihing \"sapat na\"? Handa ba akong bitawan ang isang bibilhin, promosyon o deal kung kapalit nito ang integridad ko o ang oras ko sa Diyos? Lumuluwag ang hawak ng kasakiman tuwing sadya tayong nagbibigay."
      ),
    ],
    twist: t(
      "We assume the cure for greed is to want less. But the cure Jesus gives is to want something better: \"Store up for yourselves treasures in heaven\" (Matthew 6:20). Notice He does not tell us to stop being treasure-seekers; He tells us to change banks. The heart follows the treasure, so the quickest way to a free heart is to move your treasure by giving, serving and investing in people who will last forever.",
      "Akala natin ang lunas sa kasakiman ay ang pagnanais ng mas kaunti. Pero ang lunas na ibinibigay ni Hesus ay ang pagnanais ng mas mabuti: \"Mag-imbak kayo ng kayamanan sa langit\" (Mateo 6:20). Pansinin: hindi Niya sinabing tumigil tayo sa paghahanap ng kayamanan; sinabi Niyang lumipat tayo ng bangko. Sumusunod ang puso sa kayamanan, kaya ang pinakamabilis na daan sa pusong malaya ay ilipat ang kayamanan mo sa pamamagitan ng pagbibigay, paglilingkod at pamumuhunan sa mga taong mananatili magpakailanman."
    ),
    confirm: [
      t("Matthew 6:19-21: where your treasure is, there your heart will be also.", "Mateo 6:19-21: kung nasaan ang kayamanan mo, naroon din ang puso mo."),
      t("1 Timothy 6:9-10: the love of money is a root of all kinds of evil.", "1 Timoteo 6:9-10: ang pag-ibig sa salapi ang ugat ng lahat ng uri ng kasamaan."),
      t("1 Timothy 6:17-19: be rich in good deeds, generous and willing to share.", "1 Timoteo 6:17-19: yumaman sa mabubuting gawa, mapagbigay at handang magbahagi."),
      t("Hebrews 13:5: keep your life free from the love of money and be content.", "Hebreo 13:5: ilayo ang buhay sa pag-ibig sa salapi at masiyahan sa mayroon."),
    ],
    heart: [
      t(
        "Ask the Holy Spirit to show you where \"never enough\" is ruling you: shopping, status, side hustles, saving out of fear, or comparing yourself with others. Confess it without excuses.",
        "Hilingin sa Banal na Espiritu na ipakita kung saan ka pinamumunuan ng \"hindi pa sapat\": pamimili, estado sa buhay, sideline, pag-iipon dahil sa takot, o pagkukumpara sa iba. Ipagtapat ito nang walang dahilan."
      ),
      t(
        "Practice open-handedness. Give secretly, give before you feel ready, and celebrate others' blessings. Where there is gratitude, greed cannot breathe.",
        "Sanayin ang bukas na kamay. Magbigay nang palihim, magbigay bago ka pa handa, at magalak sa pagpapala ng iba. Kung nasaan ang pasasalamat, hindi makahinga ang kasakiman."
      ),
    ],
    questions: [
      t("What do I think about most when my mind is free? Is that my treasure?", "Ano ang madalas kong iniisip kapag libre ang isip ko? Iyon ba ang kayamanan ko?"),
      t("Is there something I would find it hard to give up if Jesus asked?", "May bagay ba na mahirap kong isuko kung hilingin ni Hesus?"),
      t("Do I envy others' possessions or promotions more than I thank God for mine?", "Mas naiinggit ba ako sa ari-arian o promosyon ng iba kaysa nagpapasalamat sa akin?"),
      t("Am I investing in what will last forever: people, the gospel, character?", "Namumuhunan ba ako sa mananatili magpakailanman: tao, ebanghelyo, karakter?"),
    ],
    actions: [
      t("Give something meaningful away this week, secretly if possible.", "Magbigay ng makabuluhang bagay ngayong linggo, palihim kung maaari."),
      t("Name one purchase you are craving; wait 30 days and pray about it before buying.", "Pangalanan ang isang gustong bilhin; maghintay ng 30 araw at ipanalangin muna bago bilhin."),
      t("Write three things you already have and thank God out loud for each.", "Isulat ang tatlong bagay na mayroon ka na at pasalamatan ang Diyos nang malakas sa bawat isa."),
    ],
    prayer: t(
      "Lord, You see the hidden places where \"more\" is calling my name. Forgive me for trusting in things, for envy and for holding too tightly to what You have given. Loosen my grip and fill my heart with Yourself. Teach me to say \"enough,\" to give with joy and to invest in what lasts. Be my greatest treasure, and let my heart rest where my treasure is, in heaven with You. In Jesus' name, Amen.",
      "Panginoon, nakikita Mo ang mga lihim na sulok kung saan tinatawag ako ng \"mas marami pa.\" Patawarin Mo ako sa pagtitiwala sa mga bagay, sa inggit at sa mahigpit na paghawak sa ibinigay Mo. Luwagan Mo ang kapit ko at punuin Mo ng Sarili Mo ang puso ko. Turuan Mo akong sabihing \"sapat na,\" magbigay nang may galak at mamuhunan sa mananatili. Maging Ikaw ang pinakadakila kong kayamanan, at manahan ang puso ko kung nasaan ang kayamanan ko, sa langit kasama Ka. Sa pangalan ni Hesus, Amen."
    ),
  },
  "c-seek-first-kingdom": {
    revelation: t(
      "Anxiety is what happens when other things sit on the throne; peace is what happens when the Kingdom comes first and the Father takes care of the rest.",
      "Ang pagkabalisa ay nangyayari kapag ibang bagay ang nakaupo sa trono; ang kapayapaan ay nangyayari kapag una ang Kaharian at ang Ama na ang bahala sa iba."
    ),
    mainTruth: t(
      "\"But seek first his kingdom and his righteousness, and all these things will be given to you as well\" (Matthew 6:33). Jesus says this right after naming our everyday worries: food, drink, clothes. The Father knows you need them. The point is order: when God's rule and God's righteousness come first in our priorities, the basic needs of life fall under His care. This is not a promise of luxury; it is a promise that your Father will provide what you truly need.",
      "\"Subalit unahin ninyo ang Kanyang kaharian at ang Kanyang katuwiran, at ang lahat ng ito ay idaragdag sa inyo\" (Mateo 6:33). Sinabi ito ni Hesus matapos Niyang pangalanan ang karaniwan nating ikinababahala: pagkain, inumin, damit. Alam ng Ama na kailangan mo ang mga ito. Ang punto ay ang ayos: kapag ang paghahari ng Diyos at ang Kanyang katuwiran ang nauuna sa ating mga priyoridad, ang pangunahing pangangailangan ng buhay ay nasa Kanyang pangangalaga. Hindi ito pangako ng karangyaan; pangako ito na ibibigay ng Ama ang tunay mong kailangan."
    ),
    insight: [
      t(
        "Notice that \"seek first\" does not mean \"seek only.\" Jesus does not tell us to quit our jobs and ignore our needs. He tells us what goes at the top of the list. Many believers seek the Kingdom second or third, after career, relationships and security, and then wonder why they are anxious. Anxiety is often a signal that something else has quietly taken first place.",
        "Pansinin na ang \"unahin\" ay hindi \"ito lamang.\" Hindi sinasabi ni Hesus na iwan ang trabaho at kalimutan ang pangangailangan. Sinasabi Niya kung ano ang dapat nasa tuktok ng listahan. Maraming mananampalataya ang naghahanap ng Kaharian bilang pangalawa o pangatlo, pagkatapos ng karera, relasyon at seguridad, at nagtataka kung bakit balisa. Madalas, senyales ang pagkabalisa na may ibang bagay na tahimik na umupo sa unang puwesto."
      ),
      t(
        "The people of Haggai's day built their own paneled houses while God's house lay in ruins, and they earned wages \"to put into a purse with holes\" (Haggai 1:6). When we reverse God's order, we work hard and never feel full. The kingdom of heaven is also like a treasure hidden in a field: the man \"in his joy went and sold all he had\" and bought it (Matthew 13:44). The Kingdom is not a burden to carry but a treasure to be thrilled about.",
        "Itinayo ng mga tao noong panahon ni Hagai ang sarili nilang magagarang bahay habang wasak ang bahay ng Diyos, at kumita sila ng sahod \"para ilagay sa supot na butas-butas\" (Hagai 1:6). Kapag binaligtad natin ang ayos ng Diyos, nagsisikap tayo pero hindi nabubusog. Ang kaharian ng langit ay parang kayamanang nakatago sa bukid: ang lalaki \"sa kanyang tuwa ay ipinagbili ang lahat ng kanyang ari-arian\" at binili ito (Mateo 13:44). Ang Kaharian ay hindi pasanin kundi kayamanang nakakapagpagalak."
      ),
    ],
    life: [
      t(
        "Marites is a nurse abroad, supporting parents, siblings and her own children. Every month she lay awake counting bills and what-ifs. One night she wrote a list of her worries and, beside it, a list titled \"What God has asked me to do today.\" She began to pray first, give first, and keep her Sunday fellowship even when her schedule was tight. Her bills did not vanish, but her fear did. \"I used to carry tomorrow,\" she said. \"Now I just carry today.\"",
        "Si Marites ay nars sa ibang bansa, tumutulong sa magulang, kapatid at sa sarili niyang mga anak. Buwan-buwan, gising siya sa gabi, binibilang ang bayarin at mga \"paano kung.\" Isang gabi, isinulat niya ang listahan ng mga alalahanin niya at sa tabi nito, ang listahang pinamagatang \"Ang hiniling ng Diyos na gawin ko ngayon.\" Nagsimula siyang manalangin muna, magbigay muna, at panatilihin ang pakikisama sa simbahan tuwing Linggo kahit siksik ang iskedyul. Hindi nawala ang mga bayarin, pero nawala ang takot. \"Dati, binubuhat ko ang bukas,\" sabi niya. \"Ngayon, ang ngayon lang.\""
      ),
      t(
        "Practical ways to seek first the Kingdom: begin the day with God before the phone, choose obedience over convenience, give and serve before you are comfortable, and make big decisions by asking, \"Will this move the Kingdom forward in my life and others'?\"",
        "Praktikal na paraan para unahin ang Kaharian: simulan ang araw sa Diyos bago ang cellphone, piliin ang pagsunod kaysa sa kaginhawaan, magbigay at maglingkod bago ka komportable, at gumawa ng malalaking desisyon sa pagtatanong, \"Mapapalago ba nito ang Kaharian sa buhay ko at ng iba?\""
      ),
    ],
    twist: t(
      "We think trusting God means doing less and hoping more. But Jesus shows birds that work all day gathering food, yet do not carry panic (Matthew 6:26). Seeking first is not laziness; it is working without worry. The Kingdom twist is that when you stop grasping for security, you discover that you were already inside the safest place: the Father's care. And the righteousness and joy of the Kingdom are \"in the Holy Spirit\" (Romans 14:17), and cannot be bought, only received.",
      "Akala natin ang pagtitiwala sa Diyos ay ang paggawa ng kaunti at pag-asa nang marami. Pero ipinakita ni Hesus ang mga ibon na buong araw naghahanap ng pagkain pero hindi nagpapanik (Mateo 6:26). Ang pag-una sa Kaharian ay hindi katamaran; ito ay pagtatrabaho nang walang pag-aalala. Ang Kaharian twist: kapag tumigil ka sa pagkapit sa seguridad, matutuklasan mong nasa pinakaligtas na lugar ka na pala: ang pangangalaga ng Ama. At ang katuwiran at kagalakan ng Kaharian ay \"sa Banal na Espiritu\" (Roma 14:17), hindi mabibili, tinatanggap lamang."
    ),
    confirm: [
      t("Psalm 37:4-5: delight in the Lord and commit your way to Him.", "Awit 37:4-5: magalak sa Panginoon at ipaubaya sa Kanya ang iyong lakad."),
      t("Luke 9:57-62: following Jesus means no looking back and no delayed obedience.", "Lucas 9:57-62: ang pagsunod kay Hesus ay walang lingon sa likod at walang ipinagpapaliban."),
      t("Colossians 3:1-2: set your hearts and minds on things above.", "Colosas 3:1-2: ituon ang puso at isip sa mga bagay na nasa itaas."),
      t("Philippians 4:6-7: present your requests to God and His peace will guard your hearts.", "Filipos 4:6-7: ihayag sa Diyos ang mga kahilingan at babantayan ng Kanyang kapayapaan ang puso ninyo."),
    ],
    heart: [
      t(
        "Name what is sitting in first place right now. Surrender it and put Jesus back on the throne, and then ask Him to reorder your calendar and budget around His priorities.",
        "Pangalanan kung ano ang nasa unang puwesto ngayon. Isuko ito at ibalik si Hesus sa trono, at hilingin sa Kanyang ayusin muli ang kalendaryo at budget mo ayon sa Kanyang priyoridad."
      ),
      t(
        "Trade worry for trust. When anxiety rises, turn it into a prayer and then do the next obedient thing. Rest in a Father who knows what you need before you ask.",
        "Palitan ang pag-aalala ng pagtitiwala. Kapag sumisingaw ang pagkabalisa, gawin itong panalangin at gawin ang susunod na pagsunod. Magpahinga sa Amang alam ang kailangan mo bago ka pa humingi."
      ),
    ],
    questions: [
      t("What truly takes first place in my daily schedule and thoughts?", "Ano talaga ang nasa unang puwesto ng iskedyul at isip ko araw-araw?"),
      t("What is my biggest worry, and have I handed it to the Father?", "Ano ang pinakamalaki kong alalahanin, at naipaubaya ko na ba ito sa Ama?"),
      t("Is there an act of obedience I have been delaying?", "May pagsunod ba akong ipinagpapaliban?"),
      t("Would my life look different if the Kingdom truly came first?", "Magkakaiba ba ang buhay ko kung talagang una ang Kaharian?"),
    ],
    actions: [
      t("Give the first part of tomorrow morning to God: Scripture and prayer before your phone.", "Ibigay sa Diyos ang unang bahagi ng bukas ng umaga: Kasulatan at panalangin bago ang cellphone."),
      t("Write your top three worries and pray over each, then tear up the list as a sign of release.", "Isulat ang tatlong pinakamalaking alalahanin, ipanalangin ang bawat isa, at punitin ang listahan bilang tanda ng pag-ubaya."),
      t("Choose one concrete way to advance God's Kingdom this week: serve, give or share the gospel.", "Pumili ng isang konkretong paraan para isulong ang Kaharian ngayong linggo: maglingkod, magbigay o magbahagi ng ebanghelyo."),
    ],
    prayer: t(
      "Father, I confess that I have put many things before Your Kingdom. Forgive my worry and my divided heart. Today I place Jesus first: my time, my money, my plans and my fears. Teach me to work without panic and to trust You as the One who feeds the birds and clothes the flowers. Let Your Kingdom come in my home, my workplace and my heart. I rest in Your care and I seek You first. In Jesus' name, Amen.",
      "Ama, aaminin ko pong maraming bagay ang inuna ko kaysa sa Iyong Kaharian. Patawarin Mo ang pag-aalala ko at hating puso. Ngayon, inuuna ko si Hesus: ang oras ko, pera, plano at takot. Turuan Mo akong magtrabaho nang walang panik at magtiwala sa Iyo na nagpapakain sa mga ibon at nagdadamit sa mga bulaklak. Dumating nawa ang Iyong Kaharian sa tahanan ko, trabaho at puso. Nagpapahinga ako sa Iyong pangangalaga at hinahanap Kita muna. Sa pangalan ni Hesus, Amen."
    ),
  },
};
